import re

def rle_encode(s: str) -> str:
    """Encode string using run-length encoding with single letters and counts."""
    if not s:
        return ""

    encoded_parts = []
    current_char = s[0]
    count = 1

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            encoded_parts.append(f"{current_char}{count}")
            current_char = char
            count = 1

    # Append the last run
    encoded_parts.append(f"{current_char}{count}")

    return "".join(encoded_parts)


def rle_decode(encoded: str) -> str:
    """Decode run-length encoded string back to original."""
    if not encoded:
        return ""

    result_chars = []
    i = 0
    while i < len(encoded):
        char = encoded[i]
        i += 1
        # Parse the count (may be multi-digit)
        count = 0
        while i < len(encoded) and encoded[i].isdigit():
            count = count * 10 + int(encoded[i])
            i += 1
        result_chars.append(char * count)

    return "".join(result_chars)


# Example usage:
if __name__ == "__main__":
    print(rle_encode('aaabccc'))   # Output: a3b1c3
    print(rle_decode('a3b1c3'))   # Output: aaabccc
